%% JCAS_GeneratePubFigs.m
%  Generate all 10 publication figures from CSV output files.
%  Figures are exported as JPG (300 dpi) to the 'figures' folder.
%
%  Input  : JCAS_Results/ folder containing CSV01..CSV11 files
%           (generated by JCASFasaIMultistaticwith5GAAStandard.m or
%            JCASFasaIMultistaticwith5GAAStandard_LoopingExperiment.m)
%  Output : figures/PubFig1_Pareto.jpg  .. figures/PubFig10_PerNode_RMSE.jpg
%
%  Galih Nugraha Nurkahfi -- PR Telekomunikasi, BRIN
%  Version: 1.0

clear; clc; close all;

% ── Paths ────────────────────────────────────────────────────────────────────
csv_dir  = 'JCAS_Results';          % folder containing CSV files
out_dir  = 'figures';               % output folder for JPG
suffix   = '_Primary_BW20MHz_6nodes_ModeC';  % looping experiment suffix
                                    % set to '' if using standalone run

if ~exist(out_dir,'dir'); mkdir(out_dir); end

% ── Colour palette (consistent across all figures) ───────────────────────────
C.static  = [0.122 0.471 0.706];   % blue
C.wf      = [1.000 0.498 0.055];   % orange
C.adapt   = [0.173 0.627 0.173];   % green
C.ql      = [0.839 0.153 0.157];   % red
C.sarsa   = [0.580 0.404 0.741];   % purple
C.bandit  = [0.549 0.337 0.294];   % brown
C.slr     = [0.200 0.627 0.173];   % green for SLR lines
C.fail    = [0.839 0.153 0.157];   % red for SLR fail lines
colors    = [C.static; C.wf; C.adapt; C.ql; C.sarsa; C.bandit];
strat_names = {'Static','Water-Fill','Adaptive','Q-Learning','SARSA','Greedy Bandit'};
markers   = {'o','s','^','d','v','p'};

% ── Helper: export figure ─────────────────────────────────────────────────────
function export_fig(fh, out_dir, fname)
    set(fh,'PaperPositionMode','auto','Color','w');
    exportgraphics(fh, fullfile(out_dir,[fname '.jpg']), ...
        'Resolution',300,'BackgroundColor','white');
    fprintf('[EXPORT] %s.jpg saved\n', fname);
end

% ── Helper: read primary CSV ──────────────────────────────────────────────────
function T = read_csv(csv_dir, num, suffix)
    fname = fullfile(csv_dir, sprintf('CSV%02d_%s%s.csv', num, ...
        csv_label(num), suffix));
    if ~exist(fname,'file')
        % try without suffix
        fname = fullfile(csv_dir, sprintf('CSV%02d_%s.csv', num, csv_label(num)));
    end
    if ~exist(fname,'file')
        warning('CSV not found: %s', fname);
        T = table(); return;
    end
    % Skip header rows until we find the data header
    raw = readlines(fname);
    for i = 1:length(raw)
        if contains(raw(i),'Strategy') || contains(raw(i),'SNR_dB') || ...
           contains(raw(i),'BW_MHz')   || contains(raw(i),'Node')   || ...
           contains(raw(i),'Episode')  || contains(raw(i),'w_c')    || ...
           contains(raw(i),'Config')   || contains(raw(i),'Scenario')
            T = readtable(fname,'NumHeaderLines',i-1,'VariableNamingRule','preserve');
            return;
        end
    end
    T = readtable(fname,'VariableNamingRule','preserve');
end

function lbl = csv_label(num)
    labels = {'Paper_Summary','Pareto_Sweep','Pd_vs_SNR','PerNode_RMSE', ...
              'BW_Comparison','RL_Training','Statistical_Significance', ...
              'Sensitivity_Analysis','Convergence','Ablation','Generalization'};
    lbl = labels{num};
end

fprintf('\n=== JCAS Publication Figure Generator ===\n');
fprintf('CSV dir : %s\n', csv_dir);
fprintf('Out dir : %s\n\n', out_dir);

% ═══════════════════════════════════════════════════════════════════════════
%  PubFig2 — Bar chart: Capacity per strategy (primary scenario)
%  Source : CSV01_Paper_Summary_Primary_BW20MHz_6nodes_ModeC.csv
% ═══════════════════════════════════════════════════════════════════════════
T1 = read_csv(csv_dir, 1, suffix);
if ~isempty(T1)
    fh = figure('Units','centimeters','Position',[2 2 18 10],'Color','w');
    cap = T1.Cap_Mbps;
    b = bar(cap, 0.6, 'FaceColor','flat');
    for k = 1:length(cap)
        b.CData(k,:) = colors(k,:);
    end
    hold on;
    yline(0.2,'--','Color',C.slr,'LineWidth',1.5,'Label','5GAA SLR 0.2 Mbps');
    xticks(1:6); xticklabels(strat_names);
    xlabel('Allocation Strategy','FontSize',10);
    ylabel('Shannon Capacity (Mbps)','FontSize',10);
    title('Spectral Efficiency per Strategy — Primary Scenario (6 nodes, 20 MHz, Mode C)',...
          'FontSize',10,'FontWeight','normal');
    % value labels on bars
    for k = 1:length(cap)
        text(k, cap(k)+1, sprintf('%.1f',cap(k)), ...
             'HorizontalAlignment','center','FontSize',8,'Color',colors(k,:));
    end
    grid on; box on; ylim([0 max(cap)*1.15]);
    legend(strat_names,'Location','northeast','FontSize',8,'NumColumns',2);
    export_fig(fh, out_dir, 'PubFig2_BarKPI');
end

% ═══════════════════════════════════════════════════════════════════════════
%  PubFig1 — Pareto frontier: Capacity vs RMSE
%  Source : CSV02_Pareto_Sweep_Primary_BW20MHz_6nodes_ModeC.csv
% ═══════════════════════════════════════════════════════════════════════════
T2 = read_csv(csv_dir, 2, suffix);
if ~isempty(T2)
    fh = figure('Units','centimeters','Position',[2 2 18 11],'Color','w');
    strats_u = unique(T2.Strategy,'stable');
    hold on;
    h = gobjects(length(strats_u),1);
    for si = 1:length(strats_u)
        idx = strcmp(T2.Strategy, strats_u{si});
        rm  = T2.RMSE_m(idx);
        cp  = T2.Cap_Mbps(idx);
        col = colors(si,:);
        if length(unique(rm)) == 1  % RL: single point
            h(si) = scatter(rm(1), cp(1), 80, col, markers{si}, ...
                            'filled','LineWidth',1.5,'DisplayName',strats_u{si});
        else
            h(si) = plot(rm, cp, '-','Color',col,'LineWidth',1.8, ...
                         'Marker',markers{si},'MarkerSize',5,...
                         'MarkerFaceColor',col,'DisplayName',strats_u{si});
        end
    end
    xline(1.5,'--','Color',C.slr,'LineWidth',1.5,'Label','5GAA RMSE 1.5 m');
    xlabel('EKF RMSE (m)','FontSize',10);
    ylabel('Capacity (Mbps)','FontSize',10);
    title('Communication-Sensing Pareto Frontier — Primary Scenario',...
          'FontSize',10,'FontWeight','normal');
    legend(h,'Location','northwest','FontSize',8,'NumColumns',2);
    grid on; box on; set(gca,'XScale','log');
    export_fig(fh, out_dir, 'PubFig1_Pareto');
end

