% ═══════════════════════════════════════════════════════════════════════════
%  PubFig6 — Bootstrap CI
%  Source : CSV07_Statistical_Significance_Primary_BW20MHz_6nodes_ModeC.csv
% ═══════════════════════════════════════════════════════════════════════════
fname7 = fullfile(csv_dir, ['CSV07_Statistical_Significance' suffix '.csv']);
if ~exist(fname7,'file')
    fname7 = fullfile(csv_dir,'CSV07_Statistical_Significance_Primary_BW20MHz_6nodes_ModeC.csv');
end
if exist(fname7,'file')
    raw = readlines(fname7);
    for i=1:length(raw)
        if contains(raw(i),'Strategy')
            T7 = readtable(fname7,'NumHeaderLines',i-1,'VariableNamingRule','preserve');
            break;
        end
    end
    if exist('T7','var') && ~isempty(T7)
        fh = figure('Units','centimeters','Position',[2 2 18 10],'Color','w');
        hold on;
        n = height(T7);
        for k = 1:n
            col = colors(k,:);
            mn  = T7.Mean_Cap_Mbps(k);
            cil = T7.CI_Low95_Mbps(k);
            cih = T7.CI_High95_Mbps(k);
            % CI bar
            plot([k k],[cil cih],'-','Color',col,'LineWidth',3);
            % whisker caps
            plot([k-0.15 k+0.15],[cil cil],'-','Color',col,'LineWidth',2);
            plot([k-0.15 k+0.15],[cih cih],'-','Color',col,'LineWidth',2);
            % mean marker
            scatter(k, mn, 60, col, 'd','filled');
            text(k, mn+3, sprintf('%.1f',mn),...
                 'HorizontalAlignment','center','FontSize',8,'Color',col);
        end
        xticks(1:n);
        xticklabels(strat_names(1:n));
        xlabel('Strategy','FontSize',10);
        ylabel('Capacity (Mbps)','FontSize',10);
        title('Bootstrap 95% CI (BCa, n=1000 resamples) — Primary Scenario',...
              'FontSize',10,'FontWeight','normal');
        text(0.5, 0.95, 'p = 1.0 vs Static for all strategies (deterministic policy outcomes)',...
             'Units','normalized','FontSize',8,'Color','k',...
             'HorizontalAlignment','left','VerticalAlignment','top',...
             'BackgroundColor',[1 1 0.8],'EdgeColor',[0.8 0.8 0]);
        grid on; box on; ylim([0 130]);
        export_fig(fh, out_dir, 'PubFig6_Bootstrap_CI');
    end
end

