% ═══════════════════════════════════════════════════════════════════════════
%  PubFig10 — Per-Node EKF RMSE
%  Source : CSV04_PerNode_RMSE.csv  (standalone or primary suffix)
% ═══════════════════════════════════════════════════════════════════════════
fname4 = fullfile(csv_dir, 'CSV04_PerNode_RMSE.csv');
if ~exist(fname4,'file')
    fname4 = fullfile(csv_dir, ['CSV04_PerNode_RMSE' suffix '.csv']);
end
if exist(fname4,'file')
    raw = readlines(fname4);
    for i=1:length(raw)
        if contains(raw(i),'Node')
            T4 = readtable(fname4,'NumHeaderLines',i-1,'VariableNamingRule','preserve');
            break;
        end
    end
    if exist('T4','var') && ~isempty(T4)
        % Remove MEAN row if present
        T4 = T4(~isnan(T4.Node),:);
        n4 = height(T4);
        fh = figure('Units','centimeters','Position',[2 2 18 10],'Color','w');
        hold on;
        x = 1:n4;
        % Raw RMSE bars
        bar(x - 0.2, T4.RawRMSE_m, 0.35, 'FaceColor',[0.68 0.78 0.91],...
            'EdgeColor','none','DisplayName','Raw RMSE');
        % EKF RMSE bars coloured by pass/fail
        pass5g = strcmp(T4.Pass_5GAA,'PASS');
        for k=1:n4
            col = C.slr; if ~pass5g(k); col = C.fail; end
            bar(k+0.2, T4.EKFRMSE_m(k), 0.35,'FaceColor',col,'EdgeColor','none');
            text(k+0.2, T4.EKFRMSE_m(k)+0.1, sprintf('%.2f',T4.EKFRMSE_m(k)),...
                 'HorizontalAlignment','center','FontSize',7,'Color',col);
        end
        yline(1.5,'--','Color',C.slr,'LineWidth',1.5,...
              'Label','5GAA SLR 1.5 m','LabelHorizontalAlignment','left');
        % Node labels
        node_lbls = arrayfun(@(k) sprintf('N%d\n%s',T4.Node(k),T4.Type{k}), ...
                             1:n4,'UniformOutput',false);
        xticks(1:n4); xticklabels(node_lbls);
        xlabel('Node','FontSize',10);
        ylabel('RMSE (m)','FontSize',10);
        title('Per-Node EKF RMSE vs. Raw RMSE','FontSize',10,'FontWeight','normal');
        % Manual legend
        hp(1) = bar(nan, nan, 'FaceColor',[0.68 0.78 0.91],'EdgeColor','none');
        hp(2) = bar(nan, nan, 'FaceColor',C.slr,'EdgeColor','none');
        hp(3) = bar(nan, nan, 'FaceColor',C.fail,'EdgeColor','none');
        legend(hp,{'Raw RMSE','EKF RMSE (PASS)','EKF RMSE (FAIL)'},...
               'Location','northeast','FontSize',8);
        grid on; box on;
        export_fig(fh, out_dir, 'PubFig10_PerNode_RMSE');
    end
end

fprintf('\n=== All figures done. Check folder: %s ===\n', out_dir);
